import itertools

def solve():
    vertices = range(9)
    fixed_edges = {(1,5), (0,1), (1,3), (3,6), (2,8), (4,5), (4,6)}

    # All possible edges
    all_possible_edges = []
    for u, v in itertools.combinations(vertices, 2):
        if (u, v) not in fixed_edges:
            all_possible_edges.append((u, v))

    # We need to add some number of edges to satisfy the degree constraint.
    # Let's try to add edges one by one or use a solver.
    # Since we need at least 11 more edges, let's try to find a set of 11 edges.

    import random

    # Try a randomized approach to find a valid graph
    for _ in range(10000):
        edges = set(fixed_edges)
        # Current degrees
        degrees = {i: 0 for i in vertices}
        for u, v in edges:
            degrees[u] += 1
            degrees[v] += 1

        # Add edges until all degrees >= 4
        possible_edges = list(all_possible_edges)
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            if all(d >= 4 for d in degrees.values()):
                return list(edges)

            if degrees[u] < 4 or degrees[v] < 4:
                edges.add((u, v))
                degrees[u] += 1
                degrees[v] += 1

        if all(d >= 4 for d in degrees.values()):
            return list(edges)

    return None

result = solve()
print(result)
